import asyncio
import threading
import time
import traceback
from concurrent.futures import ThreadPoolExecutor
from queue import Empty, Full, Queue
from typing import TYPE_CHECKING, Any, Callable, Dict, List, Optional

import sglang as sgl
import torch.distributed as dist
from tensordict import TensorDict

from arealite.api.cli_args import InferenceEngineConfig
from arealite.api.engine_api import InferenceEngine
from arealite.api.io_struct import (
    LLMRequest,
    LLMResponse,
    RolloutStat,
    WeightUpdateMeta,
)
from realhf.base import logging, name_resolve, names, pkg_version

if TYPE_CHECKING:
    from arealite.api.workflow_api import RolloutWorkflow
logger = logging.getLogger(__name__)

if pkg_version.is_available("sglang"):
    if pkg_version.is_version_greater_or_equal("sglang", "0.4.4"):
        SGLANG_TOKEN_OUTPUT_IDENTIFIER = "output_ids"
    else:
        SGLANG_TOKEN_OUTPUT_IDENTIFIER = "token_ids"

ROLLOUT_POLL_WAIT_TIME = 0.4
RID_CACHE_SIZE = 128

"""
Local SGLang Inference Engine
SGLangEngine currently only supports single-controller. Cannot be used in SPMD
"""


class SGLangEngine(InferenceEngine):

    def __init__(
        self,
        config: InferenceEngineConfig,
        engine_args: Optional[Dict[str, Any]] = None,
    ):
        config.max_concurrent_rollouts = (
            config.max_concurrent_rollouts or config.consumer_batch_size
        )
        self.config = config
        self.engine_args = engine_args or {}

        qsize = config.queue_size or config.max_concurrent_rollouts * 10
        self.input_queue = Queue(maxsize=qsize)
        self.output_queue = Queue(maxsize=qsize)
        self.result_cache = []

        self.exiting = threading.Event()
        self.lock = threading.Lock()

        self.rollout_stat = RolloutStat()

        self._version = 0

    def initialize(self, addr: str | None, ft_spec: Optional[Dict[str, Any]] = None):
        self.engine = sgl.Engine(**self.engine_args)

        self.rollout_thread = threading.Thread(target=self._rollout_thread)
        self.rollout_thread.start()

    def destroy(self):
        self.exiting.set()
        self.rollout_thread.join()

        if hasattr(self, "engine") and self.engine is not None:
            try:
                self.engine.shutdown()
            except Exception as e:
                logger.warning(f"Error shutting down engine: {e}")

    def set_version(self, version):
        with self.lock:
            self._version = version

    def get_version(self):
        with self.lock:
            return self._version

    def _rollout_thread(self):
        """Thread that runs the rollout loop."""
        try:
            asyncio.run(self._rollout_thread_async())
        except Exception as e:
            traceback.print_exc()

    async def _rollout_thread_async(self):
        data = None

        rollout_tasks: Dict[str, asyncio.Task] = {}
        rid = 0

        try:
            while not self.exiting.is_set():
                # Load next data from controller
                if data is None:
                    try:
                        data, workflow = self.input_queue.get_nowait()
                        logger.info(f"Get data from puller: {data}")
                    except Empty:
                        logger.debug(f"No data from puller stream.")

                # Check capacity
                if dist.is_initialized():
                    world_size = dist.get_world_size()
                else:
                    world_size = 1

                cannot_rollout_reason = []
                capacity = max(1, self.config.max_concurrent_rollouts // world_size)
                can_rollout = len(rollout_tasks) < capacity
                if not can_rollout:
                    cannot_rollout_reason.append(
                        f"Exceeding capacity: # running tasks {len(rollout_tasks)} >= capacity {capacity}"
                    )

                # Staleness control
                version = self.get_version()
                ofp = self.config.max_head_offpolicyness
                with self.lock:
                    sample_cnt = self.rollout_stat.accepted + self.rollout_stat.running
                expected_version = sample_cnt // self.config.consumer_batch_size
                not_staled = expected_version <= ofp + version
                can_rollout &= not_staled
                if not not_staled:
                    cannot_rollout_reason.append(
                        f"Staled: expected version ({expected_version}) = "
                        f"global sample cnt ({sample_cnt}) // batch size ({self.config.consumer_batch_size}), "
                        f"current latest version {version}, "
                        f"offpolicyness {self.config.max_head_offpolicyness}."
                    )

                if not can_rollout:
                    logger.debug(
                        f"Cannot submit new rollouts. "
                        + "\n".join(cannot_rollout_reason)
                    )

                # Create new rollout task
                if can_rollout and data is not None:
                    task = asyncio.create_task(
                        workflow.arun_episode(self, data), name=str(rid)
                    )
                    rollout_tasks[str(rid)] = task

                    with self.lock:
                        self.rollout_stat.submitted += 1
                        self.rollout_stat.running += 1
                        logger.info(
                            f"Submit rollout rid {rid}. "
                            f"Submit: {self.rollout_stat.submitted}, "
                            f"running: {self.rollout_stat.running}, "
                            f"accepted: {self.rollout_stat.accepted}."
                        )

                    rid += 1
                    data = None

                # Wait for rollout completion
                tasks = list(rollout_tasks.values())
                done = []
                if tasks:
                    done, _ = await asyncio.wait(
                        tasks,
                        timeout=ROLLOUT_POLL_WAIT_TIME,
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                else:
                    await asyncio.sleep(ROLLOUT_POLL_WAIT_TIME)

                # Collect done results
                for task in done:
                    traj = await task
                    traj: TensorDict
                    task_rid = task.get_name()
                    rollout_tasks.pop(task_rid)
                    self.rollout_stat.accepted += 1

                    try:
                        self.output_queue.put_nowait(traj)
                    except Full:
                        raise RuntimeError(
                            "Output queue full. Please increase queue_size."
                        )

                    with self.lock:
                        self.rollout_stat.running -= 1
                        logger.info(
                            f"Finish rollout {task_rid}. "
                            f"Submit: {self.rollout_stat.submitted}, "
                            f"running: {self.rollout_stat.running}, "
                            f"accepted: {self.rollout_stat.accepted}."
                        )
        finally:
            # Cancel remaining tasks
            for task in rollout_tasks.values():
                if not task.done():
                    task.cancel()
                    try:
                        await task
                    except asyncio.CancelledError:
                        pass

    async def agenerate(self, req: LLMRequest) -> LLMResponse:
        """Async version of generate using local sglang engine."""
        if not hasattr(self, "engine") or self.engine is None:
            raise RuntimeError(
                "Local SGLang engine is not initialized, cannot generate."
            )

        # Prepare request payload
        gconfig = req.gconfig
        stop_token_ids = gconfig.stop_token_ids

        if gconfig.n_samples != 1:
            raise ValueError(
                "LocalSGLangEngine does not support n_samples > 1. "
                "Please call generate for multiple times with n_samples = 1."
            )
        sample_params = {
            "top_p": gconfig.top_p,
            "top_k": gconfig.top_k,
            "max_new_tokens": gconfig.max_new_tokens,
            "temperature": 0.0 if gconfig.greedy else gconfig.temperature,
            "stop_token_ids": stop_token_ids,
        }

        completions = ""
        prompt = req.text if req.text else None
        input_ids = req.input_ids if req.input_ids else None

        # Make request
        start_time = time.perf_counter()
        accumulated_output_tokens = []
        accumulated_output_logprobs = []
        accumulated_versions = []
        stop_reason = "length"
        while (
            stop_reason != "stop"
            and len(accumulated_output_tokens) < gconfig.max_new_tokens
        ):

            try:
                outputs = await self.engine.async_generate(
                    prompt=prompt,
                    input_ids=input_ids,
                    sampling_params=sample_params,
                    return_logprob=True,
                )

                completions += outputs["text"]
                if prompt is None:
                    prompt = outputs["text"]
                else:
                    prompt += outputs["text"]

                meta_info = outputs["meta_info"]
                output_tokens = [x[1] for x in meta_info["output_token_logprobs"]]
                output_logprobs = [x[0] for x in meta_info["output_token_logprobs"]]

                finish_reason = meta_info.get("finish_reason", {})
                stop_reason = finish_reason.get("type", "length")

                accumulated_output_tokens.extend(output_tokens)
                accumulated_output_logprobs.extend(output_logprobs)
                accumulated_versions.extend([-1] * len(output_tokens))

            except Exception as e:
                raise RuntimeError(f"Local SGLang engine generation failed: {e}")

        latency = time.perf_counter() - start_time

        return LLMResponse(
            completions=completions,
            input_tokens=req.input_ids if req.input_ids else [],
            output_tokens=accumulated_output_tokens,
            output_logprobs=accumulated_output_logprobs,
            output_versions=accumulated_versions,
            stop_reason=stop_reason,
            latency=latency,
            ttft=latency,
        )

    def update_weights(self, meta):
        executor = ThreadPoolExecutor(max_workers=1)
        return executor.submit(self._update_weights, meta)

    def _update_weights(self, meta: WeightUpdateMeta):
        if not hasattr(self, "engine") or self.engine is None:
            raise RuntimeError(
                "Local SGLang engine is not initialized, cannot update weights."
            )
        if meta.type == "disk":
            try:
                update_name = names.update_weights_from_disk(
                    self.config.experiment_name,
                    self.config.trial_name,
                    meta.model_version,
                )
                save_timestamp = int(name_resolve.wait(update_name, timeout=120))
                load_timestamp = time.time_ns()
                logger.info(
                    f"Begin update weights from {meta.path}, responded in {(load_timestamp - save_timestamp)/1e6:.2f} ms"
                )
                # Update weights from disk,
                self.engine.update_weights_from_disk(model_path=meta.path)

                logger.info(
                    f"Loading weights done in {(time.time_ns() - load_timestamp)/1e6:.2f} ms"
                )
                self.set_version(meta.model_version)
            except Exception as e:
                logger.error(f"Failed to update weights: {e}")
                raise
        else:
            raise NotImplementedError(f"Unsupported weight update type: {meta.type}")

    def submit(self, data: Dict[str, Any], workflow: "RolloutWorkflow") -> None:
        try:
            self.input_queue.put_nowait((data, workflow))
        except Full:
            raise RuntimeError("Input queue full. Please increase queue_size.")

    def wait(self, count: int, timeout: float, should_accept: Callable) -> TensorDict:
        tik = time.perf_counter()
        accepted = len(self.result_cache)
        while (
            accepted < count
            and not self.exiting.is_set()
            and time.perf_counter() - tik < timeout
        ):
            try:
                result = self.output_queue.get(timeout=ROLLOUT_POLL_WAIT_TIME)
                if should_accept(result):
                    self.result_cache.append(result)
                    accepted += 1
                else:
                    with self.lock:
                        self.rollout_stat.accepted -= 1
            except Empty:
                time.sleep(ROLLOUT_POLL_WAIT_TIME)
        if self.exiting.is_set():
            raise RuntimeError("Rollout engine is exiting, cannot wait for results.")
        if accepted < count:
            raise TimeoutError(
                f"Timed out waiting for {count} rollouts, " f"only received {accepted}."
            )
        results, self.result_cache = (
            self.result_cache[:count],
            self.result_cache[count:],
        )
        return TensorDict.cat(results, dim=0)

    def rollout(
        self, data: List[Dict[str, Any]], workflow: "RolloutWorkflow"
    ) -> TensorDict:
        """Submit a batch of requests to the inference engine and wait for the results."""
        for item in data:
            self.submit(item, workflow)
        return self.wait(
            count=len(data),
            timeout=self.config.request_timeout,
            should_accept=lambda x: True,
        )

import os
import time
import argparse
import sglang as sgl


def parse_args():
    parser = argparse.ArgumentParser(description="SGL Language Demo")
    parser.add_argument("--model_name", type=str, default="Qwen/Qwen3-4B-Base", help="Model name or path")
    parser.add_argument("--num_gpus", type=int, default=1, help="Number of GPUs to use for data parallelism")
    parser.add_argument("--temperature", type=float, default=0.7, help="Temperature for sampling")
    parser.add_argument("--top_p", type=float, default=0.95, help="Top-p for sampling")
    parser.add_argument("--max_new_tokens", type=int, default=128, help="Maximum number of tokens to generate")
    return parser.parse_args()


def generate(llm, prompts, sampling_params):
    outputs = llm.generate(prompts, sampling_params)
    responses = [output['text'] for output in outputs]
    return responses


def get_test_prompts():
    return [
        {
            "prompt": "Complete this sentence: The capital of France is",
            "expected": "Paris"
        },
        {
            "prompt": "What is 2+2?",
            "expected": "4"
        },
        {
            "prompt": "Translate 'hello' to Spanish:",
            "expected": "hola"
        },
        {
            "prompt": "Name a primary color:",
            "expected_options": ["red", "blue", "yellow"]
        }
    ]


def evaluate_response(response, expected):
    """Simple evaluation function to check if response contains expected answer."""
    if isinstance(expected, list):
        return any(exp.lower() in response.lower() for exp in expected)
    return expected.lower() in response.lower()


if __name__ == "__main__":
    args = parse_args()

    llm = sgl.Engine(
        model_path=args.model_name,
        dp_size=args.num_gpus,
        tp_size=1,
        device="cuda",
        context_length=1000
    )

    test_data = get_test_prompts()
    prompts = [item["prompt"] for item in test_data]


    sampling_params = {
        "temperature": args.temperature,
        "top_p": args.top_p,
        "max_new_tokens": args.max_new_tokens
    }

    # Generate responses and measure time
    t0 = time.time()
    responses = generate(llm, prompts, sampling_params)
    t1 = time.time()

    # Evaluate responses
    total_score = 0
    for i, (response, test_item) in enumerate(zip(responses, test_data)):
        expected = test_item.get("expected_options", test_item.get("expected"))
        is_correct = evaluate_response(response, expected)

        print(f"Prompt {i+1}: {test_item['prompt']}")
        print(f"Response: {response}")
        print(f"Expected: {expected}")
        print(f"Correct: {is_correct}")
        print("-" * 50)

        if is_correct:
            total_score += 1

    print(f"Accuracy: {total_score}/{len(prompts)} = {total_score / len(prompts):.2f}")
    print(f"Time taken: {t1 - t0:.4f} seconds")

    llm.shutdown()

import os
import typing as t
from typing import AsyncGenerator, Optional

import bentoml
from annotated_types import Ge, Le
from typing_extensions import Annotated

import fastapi
openai_api_app = fastapi.FastAPI()

MAX_SESSION_LEN = int(os.environ.get("MAX_SESSION_LEN", 32*1024))
MAX_TOKENS = int(os.environ.get("MAX_TOKENS", 16*1024))
NUM_GPUS = int(os.environ.get("NUM_GPUS", 1))

SYSTEM_PROMPT = """You are a helpful, respectful and honest assistant. Always answer as helpfully as possible, while being safe. Your answers should not include any harmful, unethical, racist, sexist, toxic, dangerous, or illegal content. Please ensure that your responses are socially unbiased and positive in nature.

If a question does not make any sense, or is not factually coherent, explain why instead of answering something not correct. If you don't know the answer to a question, please don't share false information."""

MODEL_ID = "RedHatAI/Llama-3.3-70B-Instruct-FP8-dynamic"

sys_pkg_cmd = "apt-get -y update && apt-get -y install libopenmpi-dev git python3-pip libnuma-dev"
runtime_image = bentoml.images.Image(
    base_image="docker.io/nvidia/cuda:12.4.1-cudnn-devel-ubuntu22.04",
    lock_python_packages=False,
).run(sys_pkg_cmd).requirements_file("requirements.txt")

@bentoml.asgi_app(openai_api_app, path="/v1")
@bentoml.service(
    name="bentosglang-llama3.3-70b-instruct-fp8-service",
    image=runtime_image,
    envs=[
        {"name": "MAX_SESSION_LEN", "value": f"{MAX_SESSION_LEN}"},
        {"name": "MAX_TOKENS", "value": f"{MAX_TOKENS}"},
        {"name": "NUM_GPUS", "value": f"{NUM_GPUS}"}
    ],
    traffic={
        "timeout": 150,
        "concurrency": 30,
    },
    resources={
        "gpu": NUM_GPUS,
        "gpu_type": "nvidia-h200-141gb",
    },
)
class SGL:

    hf_model = bentoml.models.HuggingFaceModel(
        MODEL_ID,
        exclude=['*.pth', '*.pt', 'original/**/*'],
    )

    def __init__(self) -> None:
        from transformers import AutoTokenizer
        import sglang as sgl
        from sglang.srt.server_args import ServerArgs

        server_args = ServerArgs(
            model_path=self.hf_model,
            served_model_name=MODEL_ID,
            tool_call_parser="pythonic",
            context_length=MAX_SESSION_LEN,
            mem_fraction_static=0.85,
            tp_size=NUM_GPUS,
        )
        self.engine = sgl.Engine(
            server_args=server_args
        )

        self.tokenizer = AutoTokenizer.from_pretrained(self.hf_model)

        # OpenAI endpoints
        from fastapi import Request
        from fastapi.responses import ORJSONResponse
        from sglang.srt.entrypoints.openai.protocol import (
            ChatCompletionRequest,
            CompletionRequest,
            ModelCard,
            ModelList,
        )
        from sglang.srt.entrypoints.openai.serving_chat import OpenAIServingChat
        from sglang.srt.entrypoints.openai.serving_completions import (
            OpenAIServingCompletion,
        )

        openai_serving_completion = OpenAIServingCompletion(
            self.engine.tokenizer_manager, self.engine.template_manager
        )
        openai_serving_chat = OpenAIServingChat(
            self.engine.tokenizer_manager, self.engine.template_manager
        )

        @openai_api_app.post("/completions")
        async def openai_v1_completions(request: CompletionRequest, raw_request: Request):
            return await openai_serving_completion.handle_request(request, raw_request)

        @openai_api_app.post("/chat/completions")
        async def openai_v1_chat_completions(
            request: ChatCompletionRequest, raw_request: Request
        ):
            return await openai_serving_chat.handle_request(request, raw_request)

        @openai_api_app.get("/models", response_class=ORJSONResponse)
        def available_models():
            """Show available models."""
            served_model_names = [self.engine.tokenizer_manager.served_model_name]
            model_cards = []
            for served_model_name in served_model_names:
                model_cards.append(
                    ModelCard(
                        id=served_model_name,
                        root=served_model_name,
                        max_model_len=self.engine.tokenizer_manager.model_config.context_len,
                    )
                )
            return ModelList(data=model_cards)


    @bentoml.on_shutdown
    def shutdown(self):
        self.engine.shutdown()


    @bentoml.api
    async def generate(
        self,
        prompt: str = "Explain superconductors in plain English",
        system_prompt: Optional[str] = SYSTEM_PROMPT,
        max_tokens: Annotated[int, Ge(128), Le(MAX_TOKENS)] = MAX_TOKENS,
        sampling_params: Optional[t.Dict[str, t.Any]] = None,
    ) -> AsyncGenerator[str, None]:

        if sampling_params is None:
            sampling_params = dict()
        if system_prompt is None:
            system_prompt = SYSTEM_PROMPT

        sampling_params["max_new_tokens"] = sampling_params.get("max_new_tokens", max_tokens)

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": prompt},
        ]
        prompt = self.tokenizer.apply_chat_template(messages, tokenize=False)
        stream = await self.engine.async_generate(
            prompt, sampling_params=sampling_params, stream=True
        )

        cursor = 0
        async for request_output in stream:
            text = request_output["text"][cursor:]
            cursor += len(text)
            yield text

import ray
import os
from transformers import AutoTokenizer
from reason_llm.config import *

if GENERATE_BACKEND == 'transformers':
    from transformers import AutoModelForCausalLM
    @ray.remote(num_gpus=GENERATE_PER_WORKER_GPU)
    class GenerateWorker:
        def __init__(self, model_dir, gpu_ids):
            os.environ["CUDA_VISIBLE_DEVICES"] = gpu_ids
            self.llm = AutoModelForCausalLM.from_pretrained(
                model_dir,
                torch_dtype="auto",
                device_map="auto"
            )
            self.tokenizer = AutoTokenizer.from_pretrained(model_dir)

        def generate(self, prompts, sampling_params):
            temperature = sampling_params.get("temperature", 0.1)
            if temperature > 0:
                _sampling_params = dict(
                    do_sample = True,
                    temperature=temperature,
                    max_new_tokens=sampling_params.get("max_new_tokens", 3000),
                )
            else:
                _sampling_params = dict(
                    do_sample = False,
                    max_new_tokens=sampling_params.get("max_new_tokens", 3000),
                )

            formatted_prompts = [
                self.tokenizer.apply_chat_template(
                    p, tokenize=False, add_generation_prompt=True
                )
                for p in prompts
            ]
            model_inputs = self.tokenizer(formatted_prompts,padding=True, truncation=True, return_tensors="pt").to(self.llm.device)
            generated_ids = self.llm.generate(**model_inputs, **_sampling_params)[:, model_inputs.input_ids.shape[1]: ]
            outputs = self.tokenizer.batch_decode(generated_ids, skip_special_tokens=True)
            return [
                prompt + [{"role": "assistant", "content": output}]
                # prompt + [{"role": "assistant", "content": remove_stutter(output.outputs[0].text)}]
                for prompt, output in zip(prompts, outputs)
            ]

elif GENERATE_BACKEND == 'vllm':
    from vllm import LLM, SamplingParams
    @ray.remote(num_gpus=GENERATE_PER_WORKER_GPU)
    class GenerateWorker:
        def __init__(self, model_dir, gpu_ids):
            os.environ["CUDA_VISIBLE_DEVICES"] = gpu_ids
            self.llm = LLM(
                model_dir,
                max_model_len=MAX_MODEL_LEN,
                trust_remote_code=True,
                tensor_parallel_size=GENERATE_PER_WORKER_GPU,
                enable_prefix_caching=True,
                dtype='bfloat16',
            )
            self.tokenizer = AutoTokenizer.from_pretrained(model_dir)

        def generate(self, prompts, sampling_params):

            _sampling_params = SamplingParams(
                temperature=sampling_params.get("temperature", 0.1),
                max_tokens=sampling_params.get("max_new_tokens", 3000),
            )

            formatted_prompts = [
                self.tokenizer.apply_chat_template(
                    p, tokenize=False, add_generation_prompt=True
                )
                for p in prompts
            ]
            outputs = self.llm.generate(formatted_prompts, 
                                        sampling_params=_sampling_params,
                                        use_tqdm=False)
            return [
                prompt + [{"role": "assistant", "content": output.outputs[0].text}]
                # prompt + [{"role": "assistant", "content": remove_stutter(output.outputs[0].text)}]
                for prompt, output in zip(prompts, outputs)
            ]

elif GENERATE_BACKEND == 'lmdeploy':
    from lmdeploy import pipeline, GenerationConfig, TurbomindEngineConfig
    @ray.remote(num_gpus=GENERATE_PER_WORKER_GPU)
    class GenerateWorker:
        def __init__(self, model_dir, gpu_ids):
            os.environ["CUDA_VISIBLE_DEVICES"] = gpu_ids
            backend_config = TurbomindEngineConfig(
                dtype = 'bfloat16',
                tp=GENERATE_PER_WORKER_GPU,
                enable_prefix_caching = True,
            )
            self.llm = pipeline(model_dir, backend_config=backend_config)
            self.tokenizer = AutoTokenizer.from_pretrained(model_dir)

        def generate(self, prompts, sampling_params):
            temperature = sampling_params.get("temperature", 0.1)
            do_sample = temperature > 0
            _sampling_params = GenerationConfig(
                do_sample = do_sample,
                temperature=temperature,
                max_new_tokens=sampling_params.get("max_new_tokens", 3000),
            )

            formatted_prompts = [
                self.tokenizer.apply_chat_template(
                    p, tokenize=False, add_generation_prompt=True
                )
                for p in prompts
            ]
            outputs = self.llm(formatted_prompts, gen_config=_sampling_params)
            return [
                prompt + [{"role": "assistant", "content": output.text}]
                # prompt + [{"role": "assistant", "content": remove_stutter(output.outputs[0].text)}]
                for prompt, output in zip(prompts, outputs)
            ]
elif GENERATE_BACKEND == 'sglang':
    import sglang as sgl
    @ray.remote(num_gpus=GENERATE_PER_WORKER_GPU)
    class GenerateWorker:
        def __init__(self, model_dir, gpu_ids):
            os.environ["CUDA_VISIBLE_DEVICES"] = gpu_ids

            self.llm = sgl.Engine(model_path=model_dir,tp_size = GENERATE_PER_WORKER_GPU)
            self.tokenizer = AutoTokenizer.from_pretrained(model_dir)

        def generate(self, prompts, sampling_params):
            formatted_prompts = [
                self.tokenizer.apply_chat_template(
                    p, tokenize=False, add_generation_prompt=True
                )
                for p in prompts
            ]
            outputs = self.llm.generate(formatted_prompts, sampling_params)
            return [
                prompt + [{"role": "assistant", "content": output['text']}]
                # prompt + [{"role": "assistant", "content": remove_stutter(output.outputs[0].text)}]
                for prompt, output in zip(prompts, outputs)
            ]
else:
    raise ValueError(f"Unsupported GENERATE_BACKEND: {GENERATE_BACKEND}")

import asyncio
import threading
import time
import traceback
from concurrent.futures import ThreadPoolExecutor
from queue import Empty, Full, Queue
from typing import TYPE_CHECKING, Any, Callable, Dict, List, Optional

import sglang as sgl
import torch.distributed as dist
from tensordict import TensorDict

from areal.api.cli_args import InferenceEngineConfig
from areal.api.engine_api import InferenceEngine
from areal.api.io_struct import (
    ModelRequest,
    ModelResponse,
    RolloutStat,
    WeightUpdateMeta,
)
from areal.utils import logging, name_resolve, names, pkg_version

if TYPE_CHECKING:
    from areal.api.workflow_api import RolloutWorkflow
logger = logging.getLogger(__name__)

if pkg_version.is_available("sglang"):
    if pkg_version.is_version_greater_or_equal("sglang", "0.4.4"):
        SGLANG_TOKEN_OUTPUT_IDENTIFIER = "output_ids"
    else:
        SGLANG_TOKEN_OUTPUT_IDENTIFIER = "token_ids"

ROLLOUT_POLL_WAIT_TIME = 0.4
RID_CACHE_SIZE = 128

"""
Local SGLang Inference Engine
SGLangEngine currently only supports single-controller. Cannot be used in SPMD
"""


class SGLangEngine(InferenceEngine):

    def __init__(
        self,
        config: InferenceEngineConfig,
        engine_args: Optional[Dict[str, Any]] = None,
    ):
        config.max_concurrent_rollouts = (
            config.max_concurrent_rollouts or config.consumer_batch_size
        )
        self.config = config
        self.engine_args = engine_args or {}

        qsize = config.queue_size or config.max_concurrent_rollouts * 10
        self.input_queue = Queue(maxsize=qsize)
        self.output_queue = Queue(maxsize=qsize)
        self.result_cache = []

        self.exiting = threading.Event()
        self.lock = threading.Lock()

        self.rollout_stat = RolloutStat()

        self._version = 0

    def initialize(self, addr: str | None, ft_spec: Optional[Dict[str, Any]] = None):
        self.engine = sgl.Engine(**self.engine_args)

        self.rollout_thread = threading.Thread(target=self._rollout_thread)
        self.rollout_thread.start()

    def destroy(self):
        self.exiting.set()
        self.rollout_thread.join()

        if hasattr(self, "engine") and self.engine is not None:
            try:
                self.engine.shutdown()
            except Exception as e:
                logger.warning(f"Error shutting down engine: {e}")

    def set_version(self, version):
        with self.lock:
            self._version = version

    def get_version(self):
        with self.lock:
            return self._version

    def _rollout_thread(self):
        """Thread that runs the rollout loop."""
        try:
            asyncio.run(self._rollout_thread_async())
        except Exception as e:
            traceback.print_exc()
            raise e

    async def _rollout_thread_async(self):
        data = None

        rollout_tasks: Dict[str, asyncio.Task] = {}
        rid = 0

        try:
            while not self.exiting.is_set():
                # Load next data from controller
                if data is None:
                    try:
                        data, workflow = self.input_queue.get_nowait()
                        logger.info(f"Get data from puller: {data}")
                    except Empty:
                        logger.debug(f"No data from puller stream.")

                # Check capacity
                if dist.is_initialized():
                    world_size = dist.get_world_size()
                else:
                    world_size = 1

                cannot_rollout_reason = []
                capacity = max(1, self.config.max_concurrent_rollouts // world_size)
                can_rollout = len(rollout_tasks) < capacity
                if not can_rollout:
                    cannot_rollout_reason.append(
                        f"Exceeding capacity: # running tasks {len(rollout_tasks)} >= capacity {capacity}"
                    )

                # Staleness control
                version = self.get_version()
                ofp = self.config.max_head_offpolicyness
                with self.lock:
                    sample_cnt = self.rollout_stat.accepted + self.rollout_stat.running
                expected_version = sample_cnt // self.config.consumer_batch_size
                not_staled = expected_version <= ofp + version
                can_rollout &= not_staled
                if not not_staled:
                    cannot_rollout_reason.append(
                        f"Staled: expected version ({expected_version}) = "
                        f"global sample cnt ({sample_cnt}) // batch size ({self.config.consumer_batch_size}), "
                        f"current latest version {version}, "
                        f"offpolicyness {self.config.max_head_offpolicyness}."
                    )

                if not can_rollout:
                    logger.debug(
                        f"Cannot submit new rollouts. "
                        + "\n".join(cannot_rollout_reason)
                    )

                # Create new rollout task
                if can_rollout and data is not None:
                    task = asyncio.create_task(
                        workflow.arun_episode(self, data), name=str(rid)
                    )
                    rollout_tasks[str(rid)] = task

                    with self.lock:
                        self.rollout_stat.submitted += 1
                        self.rollout_stat.running += 1
                        logger.info(
                            f"Submit rollout rid {rid}. "
                            f"Submit: {self.rollout_stat.submitted}, "
                            f"running: {self.rollout_stat.running}, "
                            f"accepted: {self.rollout_stat.accepted}."
                        )

                    rid += 1
                    data = None

                # Wait for rollout completion
                tasks = list(rollout_tasks.values())
                done = []
                if tasks:
                    done, _ = await asyncio.wait(
                        tasks,
                        timeout=ROLLOUT_POLL_WAIT_TIME,
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                else:
                    await asyncio.sleep(ROLLOUT_POLL_WAIT_TIME)

                # Collect done results
                for task in done:
                    traj = await task
                    traj: TensorDict
                    task_rid = task.get_name()
                    rollout_tasks.pop(task_rid)
                    self.rollout_stat.accepted += 1

                    try:
                        self.output_queue.put_nowait(traj)
                    except Full:
                        raise RuntimeError(
                            "Output queue full. Please increase queue_size."
                        )

                    with self.lock:
                        self.rollout_stat.running -= 1
                        logger.info(
                            f"Finish rollout {task_rid}. "
                            f"Submit: {self.rollout_stat.submitted}, "
                            f"running: {self.rollout_stat.running}, "
                            f"accepted: {self.rollout_stat.accepted}."
                        )
        finally:
            # Cancel remaining tasks
            for task in rollout_tasks.values():
                if not task.done():
                    task.cancel()
                    try:
                        await task
                    except asyncio.CancelledError:
                        pass

    async def agenerate(self, req: ModelRequest) -> ModelResponse:
        """Async version of generate using local sglang engine."""
        if not hasattr(self, "engine") or self.engine is None:
            raise RuntimeError(
                "Local SGLang engine is not initialized, cannot generate."
            )

        # Prepare request payload
        gconfig = req.gconfig
        stop_token_ids = gconfig.stop_token_ids

        if gconfig.n_samples != 1:
            raise ValueError(
                "LocalSGLangEngine does not support n_samples > 1. "
                "Please call generate for multiple times with n_samples = 1."
            )
        sample_params = {
            "top_p": gconfig.top_p,
            "top_k": gconfig.top_k,
            "max_new_tokens": gconfig.max_new_tokens,
            "temperature": 0.0 if gconfig.greedy else gconfig.temperature,
            "stop_token_ids": stop_token_ids,
        }

        completions = ""
        prompt = req.text if req.text else None
        input_ids = req.input_ids if req.input_ids else None

        # Make request
        start_time = time.perf_counter()
        accumulated_output_tokens = []
        accumulated_output_logprobs = []
        accumulated_versions = []
        stop_reason = "length"
        while (
            stop_reason != "stop"
            and len(accumulated_output_tokens) < gconfig.max_new_tokens
        ):

            try:
                outputs = await self.engine.async_generate(
                    prompt=prompt,
                    input_ids=input_ids,
                    sampling_params=sample_params,
                    return_logprob=True,
                )

                completions += outputs["text"]
                if prompt is None:
                    prompt = outputs["text"]
                else:
                    prompt += outputs["text"]

                meta_info = outputs["meta_info"]
                output_tokens = [x[1] for x in meta_info["output_token_logprobs"]]
                output_logprobs = [x[0] for x in meta_info["output_token_logprobs"]]

                finish_reason = meta_info.get("finish_reason", {})
                stop_reason = finish_reason.get("type", "length")

                accumulated_output_tokens.extend(output_tokens)
                accumulated_output_logprobs.extend(output_logprobs)
                accumulated_versions.extend([-1] * len(output_tokens))

            except Exception as e:
                raise RuntimeError(f"Local SGLang engine generation failed: {e}")

        latency = time.perf_counter() - start_time

        return ModelResponse(
            completions=completions,
            input_tokens=req.input_ids if req.input_ids else [],
            output_tokens=accumulated_output_tokens,
            output_logprobs=accumulated_output_logprobs,
            output_versions=accumulated_versions,
            stop_reason=stop_reason,
            latency=latency,
            ttft=latency,
        )

    def update_weights(self, meta):
        executor = ThreadPoolExecutor(max_workers=1)
        return executor.submit(self._update_weights, meta)

    def _update_weights(self, meta: WeightUpdateMeta):
        if not hasattr(self, "engine") or self.engine is None:
            raise RuntimeError(
                "Local SGLang engine is not initialized, cannot update weights."
            )
        if meta.type == "disk":
            try:
                update_name = names.update_weights_from_disk(
                    self.config.experiment_name,
                    self.config.trial_name,
                    meta.model_version,
                )
                save_timestamp = int(name_resolve.wait(update_name, timeout=120))
                load_timestamp = time.time_ns()
                logger.info(
                    f"Begin update weights from {meta.path}, responded in {(load_timestamp - save_timestamp)/1e6:.2f} ms"
                )
                # Update weights from disk,
                self.engine.update_weights_from_disk(model_path=meta.path)

                logger.info(
                    f"Loading weights done in {(time.time_ns() - load_timestamp)/1e6:.2f} ms"
                )
                self.set_version(meta.model_version)
            except Exception as e:
                logger.error(f"Failed to update weights: {e}")
                raise
        else:
            raise NotImplementedError(f"Unsupported weight update type: {meta.type}")

    def submit(self, data: Dict[str, Any], workflow: "RolloutWorkflow") -> None:
        try:
            self.input_queue.put_nowait((data, workflow))
        except Full:
            raise RuntimeError("Input queue full. Please increase queue_size.")

    def wait(self, count: int, timeout: float, should_accept: Callable) -> TensorDict:
        tik = time.perf_counter()
        accepted = len(self.result_cache)
        while (
            accepted < count
            and not self.exiting.is_set()
            and time.perf_counter() - tik < timeout
        ):
            try:
                result = self.output_queue.get(timeout=ROLLOUT_POLL_WAIT_TIME)
                if should_accept(result):
                    self.result_cache.append(result)
                    accepted += 1
                else:
                    with self.lock:
                        self.rollout_stat.accepted -= 1
            except Empty:
                time.sleep(ROLLOUT_POLL_WAIT_TIME)
        if self.exiting.is_set():
            raise RuntimeError("Rollout engine is exiting, cannot wait for results.")
        if accepted < count:
            raise TimeoutError(
                f"Timed out waiting for {count} rollouts, " f"only received {accepted}."
            )
        results, self.result_cache = (
            self.result_cache[:count],
            self.result_cache[count:],
        )
        return TensorDict.cat(results, dim=0)

    def rollout(
        self, data: List[Dict[str, Any]], workflow: "RolloutWorkflow"
    ) -> TensorDict:
        """Submit a batch of requests to the inference engine and wait for the results."""
        for item in data:
            self.submit(item, workflow)
        return self.wait(
            count=len(data),
            timeout=self.config.request_timeout,
            should_accept=lambda x: True,
        )

import os
import typing as t
from typing import AsyncGenerator, Optional

import bentoml
from annotated_types import Ge, Le
from typing_extensions import Annotated

import fastapi
openai_api_app = fastapi.FastAPI()

MAX_SESSION_LEN = int(os.environ.get("MAX_SESSION_LEN", 8*1024))
MAX_TOKENS = int(os.environ.get("MAX_TOKENS", 4*1024))
NUM_GPUS = int(os.environ.get("NUM_GPUS", 2))

SYSTEM_PROMPT = """You are a helpful, respectful and honest assistant. Always answer as helpfully as possible, while being safe. Your answers should not include any harmful, unethical, racist, sexist, toxic, dangerous, or illegal content. Please ensure that your responses are socially unbiased and positive in nature.

If a question does not make any sense, or is not factually coherent, explain why instead of answering something not correct. If you don't know the answer to a question, please don't share false information."""

MODEL_ID = "neuralmagic/Meta-Llama-3.1-70B-Instruct-quantized.w8a8"

sys_pkg_cmd = "apt-get -y update && apt-get -y install libopenmpi-dev git python3-pip"
runtime_image = bentoml.images.Image(
    base_image="docker.io/nvidia/cuda:12.4.1-cudnn-devel-ubuntu22.04",
    lock_python_packages=False,
).run(sys_pkg_cmd).requirements_file("requirements.txt")

@bentoml.asgi_app(openai_api_app, path="/v1")
@bentoml.service(
    name="bentosglang-llama3.3-70b-instruct-int8-service",
    image=runtime_image,
    envs=[
        {"name": "MAX_SESSION_LEN", "value": f"{MAX_SESSION_LEN}"},
        {"name": "MAX_TOKENS", "value": f"{MAX_TOKENS}"},
        {"name": "NUM_GPUS", "value": f"{NUM_GPUS}"}
    ],
    traffic={
        "timeout": 150,
        "concurrency": 10,
    },
    resources={
        "gpu": NUM_GPUS,
        "gpu_type": "nvidia-a100-80gb",
    },
)
class SGL:

    hf_model = bentoml.models.HuggingFaceModel(
        MODEL_ID,
        exclude=['*.pth', '*.pt', 'original/**/*'],
    )

    def __init__(self) -> None:
        from transformers import AutoTokenizer
        import sglang as sgl
        from sglang.srt.server_args import ServerArgs

        server_args = ServerArgs(
            model_path=self.hf_model,
            served_model_name=MODEL_ID,
            tool_call_parser="llama3",
            context_length=MAX_SESSION_LEN,
            mem_fraction_static=0.85,
            tp_size=NUM_GPUS,
        )
        self.engine = sgl.Engine(
            server_args=server_args
        )

        self.tokenizer = AutoTokenizer.from_pretrained(self.hf_model)

        # OpenAI endpoints
        from fastapi import Request
        from fastapi.responses import ORJSONResponse
        from sglang.srt.openai_api.adapter import (
            v1_chat_completions,
            v1_completions,
        )
        from sglang.srt.openai_api.protocol import ModelCard, ModelList

        @openai_api_app.post("/completions")
        async def openai_v1_completions(raw_request: Request):
            return await v1_completions(self.engine.tokenizer_manager, raw_request)


        @openai_api_app.post("/chat/completions")
        async def openai_v1_chat_completions(raw_request: Request):
            return await v1_chat_completions(self.engine.tokenizer_manager, raw_request)

        @openai_api_app.get("/models", response_class=ORJSONResponse)
        def available_models():
            """Show available models."""
            served_model_names = [self.engine.tokenizer_manager.served_model_name]
            model_cards = []
            for served_model_name in served_model_names:
                model_cards.append(ModelCard(id=served_model_name, root=served_model_name))
            return ModelList(data=model_cards)


    @bentoml.on_shutdown
    def shutdown(self):
        self.engine.shutdown()


    @bentoml.api
    async def generate(
        self,
        prompt: str = "Explain superconductors in plain English",
        system_prompt: Optional[str] = SYSTEM_PROMPT,
        max_tokens: Annotated[int, Ge(128), Le(MAX_TOKENS)] = MAX_TOKENS,
        sampling_params: Optional[t.Dict[str, t.Any]] = None,
    ) -> AsyncGenerator[str, None]:

        if sampling_params is None:
            sampling_params = dict()
        if system_prompt is None:
            system_prompt = SYSTEM_PROMPT

        sampling_params["max_new_tokens"] = sampling_params.get("max_new_tokens", max_tokens)

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": prompt},
        ]
        prompt = self.tokenizer.apply_chat_template(messages, tokenize=False)
        stream = await self.engine.async_generate(
            prompt, sampling_params=sampling_params, stream=True
        )

        cursor = 0
        async for request_output in stream:
            text = request_output["text"][cursor:]
            cursor += len(text)
            yield text

import os
import json
import argparse
from datasets import load_dataset
from datetime import datetime
from transformers import AutoTokenizer
import sglang as sgl


system_prompt: str = "Solve the following math problem efficiently and clearly:

- For simple problems (2 steps or fewer):
Provide a concise solution with minimal explanation.

- For complex problems (3 steps or more):
Use this step-by-step format:

## Step 1: [Concise description]
[Brief explanation and calculations]

## Step 2: [Concise description]
[Brief explanation and calculations]

...

Regardless of the approach, always conclude with:

Therefore, the final answer is: $\boxed{answer}$. I hope it is correct.

Where [answer] is just the final number or expression that solves the problem."
custom_chat_template: str = '{%- if custom_tools is defined %}
    {%- set tools = custom_tools %}
{%- endif %}
{%- if not tools_in_user_message is defined %}
    {%- set tools_in_user_message = true %}
{%- endif %}
{%- if not date_string is defined %}
    {%- if strftime_now is defined %}
        {%- set date_string = strftime_now("%d %b %Y") %}
    {%- else %}
        {%- set date_string = "26 Jul 2024" %}
    {%- endif %}
{%- endif %}
{%- if not tools is defined %}
    {%- set tools = none %}
{%- endif %}

{#- This block extracts the system message, so we can slot it into the right place. #}
{%- if messages[0]['role'] == 'system' %}
    {%- set system_message = messages[0]['content']|trim %}
    {%- set messages = messages[1:] %}
{%- else %}
    {%- set system_message = "" %}
{%- endif %}

{#- System message #}
{{- "<|start_header_id|>system<|end_header_id|>\n\n" }}
{%- if tools is not none %}
    {{- "Environment: ipython\n" }}
{%- endif %}
{{- "Cutting Knowledge Date: December 2023\n" }}
{{- "Today Date: " + date_string + "\n\n" }}
{%- if tools is not none and not tools_in_user_message %}
    {{- "You have access to the following functions. To call a function, please respond with JSON for a function call." }}
    {{- 'Respond in the format {"name": function name, "parameters": dictionary of argument name and its value}.' }}
    {{- "Do not use variables.\n\n" }}
    {%- for t in tools %}
        {{- t | tojson(indent=4) }}
        {{- "\n\n" }}
    {%- endfor %}
{%- endif %}
{{- system_message }}
{{- "<|eot_id|>" }}

{#- Custom tools are passed in a user message with some extra guidance #}
{%- if tools_in_user_message and not tools is none %}
    {#- Extract the first user message so we can plug it in here #}
    {%- if messages | length != 0 %}
        {%- set first_user_message = messages[0]['content']|trim %}
        {%- set messages = messages[1:] %}
    {%- else %}
        {{- raise_exception("Cannot put tools in the first user message when there's no first user message!") }}
{%- endif %}
    {{- '<|start_header_id|>user<|end_header_id|>\n\n' -}}
    {{- "Given the following functions, please respond with a JSON for a function call " }}
    {{- "with its proper arguments that best answers the given prompt.\n\n" }}
    {{- 'Respond in the format {"name": function name, "parameters": dictionary of argument name and its value}.' }}
    {{- "Do not use variables.\n\n" }}
    {%- for t in tools %}
        {{- t | tojson(indent=4) }}
        {{- "\n\n" }}
    {%- endfor %}
    {{- first_user_message + "<|eot_id|>"}}
{%- endif %}

{%- for message in messages %}
    {%- if not (message.role == 'ipython' or message.role == 'tool' or 'tool_calls' in message) %}
        {{- '<|start_header_id|>' + message['role'] + '<|end_header_id|>\n\n'+ message['content'] + '<|eot_id|>' }}
    {%- elif 'tool_calls' in message %}
        {%- if not message.tool_calls|length == 1 %}
            {{- raise_exception("This model only supports single tool-calls at once!") }}
        {%- endif %}
        {%- set tool_call = message.tool_calls[0].function %}
        {{- '<|start_header_id|>assistant<|end_header_id|>\n\n' -}}
        {{- '{"name": "' + tool_call.name + '", ' }}
        {{- '"parameters": ' }}
        {{- tool_call.arguments | tojson }}
        {{- "}" }}
        {{- "<|eot_id|>" }}
    {%- elif message.role == "tool" or message.role == "ipython" %}
        {{- "<|start_header_id|>ipython<|end_header_id|>\n\n" }}
        {%- if message.content is mapping or message.content is iterable %}
            {{- message.content | tojson }}
        {%- else %}
            {{- message.content }}
        {%- endif %}
        {{- "<|eot_id|>" }}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|start_header_id|>assistant<|end_header_id|>\n\n' }}
{%- endif %}
'


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--model_name", type=str, default="meta-llama/Llama-3.2-1B-Instruct")
    parser.add_argument("--dataset_name", type=str, default="HuggingFaceH4/MATH-500")
    parser.add_argument("--system_prompt", type=str, default=system_prompt)
    parser.add_argument("--temperature", type=float, default=0.8)
    parser.add_argument("--top_p", type=float, default=1.0)
    parser.add_argument("--top_k", type=int, default=-1)
    parser.add_argument("--num_samples", type=int, default=1024)
    parser.add_argument("--max_new_tokens", type=int, default=4096)
    parser.add_argument("--output_dir", type=str, default="./outputs_sgl_4096")
    parser.add_argument("--use_custom_chat_template", type=bool, default=False)
    args = parser.parse_args()
    print(args)

    os.makedirs(args.output_dir, exist_ok=True)


    dataset = load_dataset(args.dataset_name, split='test')
    problems = [row["problem"] for row in dataset]


    llm = sgl.Engine(model_path=args.model_name)
    tokenizer = AutoTokenizer.from_pretrained(args.model_name)
    if args.use_custom_chat_template:
        tokenizer.chat_template = custom_chat_template


    sampling_params = {"temperature": args.temperature, 
                       "top_p": args.top_p, 
                       "top_k": args.top_k, 
                       "max_new_tokens": args.max_new_tokens,
                       "n": args.num_samples}



    # Iterate over prompts with progress bar
    for idx, problem in enumerate(problems):
        message = [
            {"role": "system", "content": args.system_prompt},
            {"role": "user", "content": problem}
        ]
        prompts = [tokenizer.apply_chat_template(message, add_generation_prompt=True, tokenize=False)]
        outputs = llm.generate(prompts, sampling_params)

        responses = [
            {"role": "assistant", "content": output["text"].strip()}
            for output in outputs
        ]

        data = {
            "test_id": idx+1,
            "problem": problem,
            "subject": dataset[idx]["subject"],
            "level": dataset[idx]["level"],
            "answer": dataset[idx]["answer"],
            "prompts": prompts,
            "temperature": args.temperature,
            "max_new_tokens": args.max_new_tokens,
            "greedy_responses": responses,

        }

        # Define individual JSON filename
        individual_filename = f"test_{idx+1}.json"
        individual_path = os.path.join(args.output_dir, individual_filename)

        # Save the individual JSON file
        with open(individual_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=4, ensure_ascii=False)
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        print(f"{timestamp},  save {individual_filename}")

    print(f"Generation completed. All data saved to '{args.output_dir}'.")

from typing import Optional, Any, Union

import torch

import sglang as sgl

from .abstract_model import AbstractModel, MODEL_NAME


class SglangModel(AbstractModel):

    def __init__(self) -> None:
        super().__init__()

        self._base_model = None
        self.llm = sgl.Engine(model_path=MODEL_NAME, skip_tokenizer_init=True, tp_size=1)

    @property
    def base_model(self):
        return self._base_model

    def prepare_prompt_tokens(self, prompt: torch.Tensor) -> Union[list[int], torch.Tensor]:
        return prompt.squeeze().tolist()

    def generate(self, prompt_token_ids: Union[list[int], torch.Tensor], max_new_tokens: int,
                 stop_token_id: Optional[int] = None) -> Any:
        sampling_params = {"temperature": 0, "max_new_tokens": max_new_tokens, "stop_token_ids": [stop_token_id],
                           "ignore_eos": True if stop_token_id is None else False}
        output = self.llm.generate(input_ids=prompt_token_ids, sampling_params=sampling_params)

        return output["token_ids"]

    @staticmethod
    def get_name() -> str:
        return "sglang"

import typing as t
from typing import AsyncGenerator, Optional

import bentoml
from annotated_types import Ge, Le
from typing_extensions import Annotated

import fastapi
openai_api_app = fastapi.FastAPI()

MAX_MODEL_LEN = 4096
MAX_TOKENS = 1024

SYSTEM_PROMPT = """You are a helpful, respectful and honest assistant. Always answer as helpfully as possible, while being safe. Your answers should not include any harmful, unethical, racist, sexist, toxic, dangerous, or illegal content. Please ensure that your responses are socially unbiased and positive in nature.

If a question does not make any sense, or is not factually coherent, explain why instead of answering something not correct. If you don't know the answer to a question, please don't share false information."""

MODEL_ID = "meta-llama/Meta-Llama-3.1-8B-Instruct"

sys_pkg_cmd = "apt-get -y update && apt-get -y install git python3-pip libnuma-dev"
runtime_image = bentoml.images.Image(
    base_image="docker.io/nvidia/cuda:12.4.1-cudnn-devel-ubuntu22.04",
).run(sys_pkg_cmd).requirements_file("requirements.txt")

@bentoml.mount_asgi_app(openai_api_app, path="/v1")
@bentoml.service(
    name="bentosglang-llama3.1-8b-instruct-service",
    image=runtime_image,
    envs=[{"name": "HF_TOKEN"}],
    traffic={
        "timeout": 600,
        "concurrency": 256,
    },
    resources={
        "gpu": 1,
        "gpu_type": "nvidia-l4",
    },
)
class SGL:

    hf_model = bentoml.models.HuggingFaceModel(
        MODEL_ID,
        exclude=['*.pth', '*.pt', 'original/**/*'],
    )

    def __init__(self) -> None:
        from transformers import AutoTokenizer
        import sglang as sgl
        from sglang.srt.server_args import ServerArgs
        from fastapi import Request
        from fastapi.responses import ORJSONResponse
        from sglang.srt.entrypoints.openai.protocol import (
            ChatCompletionRequest,
            CompletionRequest,
            ModelCard,
            ModelList,
        )
        from sglang.srt.entrypoints.openai.serving_chat import OpenAIServingChat
        from sglang.srt.entrypoints.openai.serving_completions import (
            OpenAIServingCompletion,
        )

        server_args = ServerArgs(
            model_path=self.hf_model,
            served_model_name=MODEL_ID,
            tool_call_parser="llama3",
            context_length=MAX_MODEL_LEN,
            mem_fraction_static=0.85,
        )
        self.engine = sgl.Engine(
            server_args=server_args
        )

        self.tokenizer = AutoTokenizer.from_pretrained(MODEL_ID)

        # OpenAI endpoints
        openai_serving_completion = OpenAIServingCompletion(
            self.engine.tokenizer_manager, self.engine.template_manager
        )
        openai_serving_chat = OpenAIServingChat(
            self.engine.tokenizer_manager, self.engine.template_manager
        )

        @openai_api_app.post("/completions")
        async def openai_v1_completions(request: CompletionRequest, raw_request: Request):
            return await openai_serving_completion.handle_request(request, raw_request)

        @openai_api_app.post("/chat/completions")
        async def openai_v1_chat_completions(
            request: ChatCompletionRequest, raw_request: Request
        ):
            return await openai_serving_chat.handle_request(request, raw_request)

        @openai_api_app.get("/models", response_class=ORJSONResponse)
        def available_models():
            """Show available models."""
            served_model_names = [self.engine.tokenizer_manager.served_model_name]
            model_cards = []
            for served_model_name in served_model_names:
                model_cards.append(
                    ModelCard(
                        id=served_model_name,
                        root=served_model_name,
                        max_model_len=self.engine.tokenizer_manager.model_config.context_len,
                    )
                )
            return ModelList(data=model_cards)


    @bentoml.on_shutdown
    def shutdown(self):
        self.engine.shutdown()


    @bentoml.api
    async def generate(
        self,
        prompt: str = "Explain superconductors in plain English",
        system_prompt: Optional[str] = SYSTEM_PROMPT,
        max_tokens: Annotated[int, Ge(128), Le(MAX_TOKENS)] = MAX_TOKENS,
        sampling_params: Optional[t.Dict[str, t.Any]] = None,
    ) -> AsyncGenerator[str, None]:

        if sampling_params is None:
            sampling_params = dict()
        if system_prompt is None:
            system_prompt = SYSTEM_PROMPT

        sampling_params["max_new_tokens"] = sampling_params.get("max_new_tokens", max_tokens)

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": prompt},
        ]
        prompt = self.tokenizer.apply_chat_template(messages, tokenize=False)
        stream = await self.engine.async_generate(
            prompt, sampling_params=sampling_params, stream=True
        )

        cursor = 0
        async for request_output in stream:
            text = request_output["text"][cursor:]
            cursor += len(text)
            yield text

import os
